private final class ChannelTransformGate:@unchecked Sendable{
  let condition=NSCondition();var ready=false
  func wait(){condition.lock();while !ready{condition.wait()};condition.unlock()}
  func release(){condition.lock();ready=true;condition.broadcast();condition.unlock()}
}
final class ChannelTransformWorkflowTests:XCTestCase{
  func fixture(_ depth:PixelDepth = .u8,kind:Int=0,selected:Bool=false)throws->(CraftDocument,ChannelPlaneTarget){
