    for y in 3..<13{for x in 4..<16{let v=Float(x+y)/32;plane.setPixel(x:x,y:y,Pixel(v,v,v))}}
    var channel=AlphaChannel(name:"Target",pixels:plane);channel.options.opacity=0.3;channel.options.color=Pixel(0,1,0)
    if kind==1{channel.spot=SpotInk(color:Pixel(0.4,0.2,0.6),solidity:0.8);if depth == .f32{channel.psdSpotGray=try plane.mappedStoredSamples{p in let v=1-p.r;return Pixel(v,v,v)};channel.pixels=try plane.mappedStoredSamples{p in let v=1-(1-p.r);return Pixel(v,v,v)}}}
    let target:ChannelPlaneTarget;if kind==2{d.quickMask=channel;target = .quickMask}else{d.alphaChannels=[channel];target = .alpha(channel.id)};if selected{d.selection = .init(x:4,y:3,width:12,height:10)};return(d,target)
