  @MainActor func testInvalidBusyStaleRevokedCancelledAndChangedTargetAreAtomic()async throws{
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let(source,target)=try self.fixture(),s=doc.store;s.session=EditorSession(document:source);try self.choose(s,target);try service.share(doc);let params:[String:Any]=["target":self.identifier(target),"matrix":[1,0,2,0,1,1,0,0,1]]
      for extra:[String:Any] in [["target":"bad"],["matrix":[1,2]],["matrix":[0,0,0,0,0,0,0,0,0]],["backgroundValue":true],["backgroundValue":1.1],["copy":1],["interpolation":"bad"],["unknown":1]]{let code=try await h.edit(service,doc,"channel.transform",params.merging(extra){_,b in b});XCTAssertEqual(code,400);XCTAssertEqual(s.document,source)}
      s.alphaEditingID=nil;let context=try await h.edit(service,doc,"channel.transform",params);XCTAssertEqual(context,422);try self.choose(s,target);let stale=try await h.edit(service,doc,"channel.transform",params,revision:"old");XCTAssertEqual(stale,409);s.beginTransform();let busy=try await h.edit(service,doc,"channel.transform",params);XCTAssertEqual(busy,409);s.cancelTransform()
      for revoke in [false,true]{let gate=ChannelTransformGate();defer{gate.release()};try service.share(doc);try self.choose(s,target);s.channelTransformPreparation={_,request in gate.wait();try Task.checkCancellation();return .transformChannel(request)};let task=Task{try await h.edit(service,doc,"channel.transform",params)};let until=Date().addingTimeInterval(10);while !s.geometryBusy && Date()<until{await Task.yield()};XCTAssertTrue(s.geometryBusy);if revoke{service.revoke(try XCTUnwrap(service.shares.first?.id))}else{s.alphaEditingID=nil};gate.release();let code=try await task.value;XCTAssertEqual(code,409);XCTAssertEqual(s.document,source)}
      try self.choose(s,target);let native=ChannelTransformGate();defer{native.release()};s.channelTransformPreparation={_,request in native.wait();try Task.checkCancellation();return .transformChannel(request)};s.beginTransform();let session=try XCTUnwrap(s.selectionTransform);s.commitTransform();s.cancelTransform();native.release();await session.commitTask?.value;XCTAssertEqual(s.document,source);XCTAssertFalse(s.geometryBusy)
    }
  }
